-- ============================================================================
-- V17__drop_accidental_hibernate6_unique_constraints.sql
-- Removes accidental single-column UNIQUE constraints / indexes generated by
-- Hibernate 6 on legacy @OneToOne associations that are domain @ManyToOne:
--   - public.transaction(inputmeasureunittype_id)
--   - public.transaction(sourcestockorder_id)
--   - public.stockorder(consumercompanycustomer_id)
-- Replaces them with standard non-unique B-tree foreign-key indexes.
-- ============================================================================

DO $$
DECLARE
    rec RECORD;
BEGIN
    -- 1. Drop table-level UNIQUE constraints on those 3 foreign-key columns
    FOR rec IN
        SELECT cl.relname AS table_name,
               co.conname AS constraint_name
        FROM pg_constraint co
        JOIN pg_class cl ON cl.oid = co.conrelid
        JOIN pg_namespace ns ON ns.oid = cl.relnamespace
        JOIN pg_attribute at ON at.attrelid = cl.oid AND at.attnum = co.conkey[1]
        WHERE ns.nspname = 'public'
          AND co.contype = 'u'
          AND array_length(co.conkey, 1) = 1
          AND (
              (cl.relname = 'transaction' AND at.attname IN ('inputmeasureunittype_id', 'sourcestockorder_id'))
              OR (cl.relname = 'stockorder' AND at.attname = 'consumercompanycustomer_id')
          )
    LOOP
        EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I', rec.table_name, rec.constraint_name);
    END LOOP;

    -- 2. Drop any standalone UNIQUE indexes not backed by a pg_constraint row
    FOR rec IN
        SELECT tbl.relname AS table_name,
               idx.relname AS index_name
        FROM pg_index ix
        JOIN pg_class tbl ON tbl.oid = ix.indrelid
        JOIN pg_class idx ON idx.oid = ix.indexrelid
        JOIN pg_namespace ns ON ns.oid = tbl.relnamespace
        JOIN pg_attribute at ON at.attrelid = tbl.oid AND at.attnum = ix.indkey[0]
        LEFT JOIN pg_constraint co ON co.conindid = ix.indexrelid
        WHERE ns.nspname = 'public'
          AND ix.indisunique = true
          AND ix.indisprimary = false
          AND ix.indnatts = 1
          AND co.oid IS NULL
          AND (
              (tbl.relname = 'transaction' AND at.attname IN ('inputmeasureunittype_id', 'sourcestockorder_id'))
              OR (tbl.relname = 'stockorder' AND at.attname = 'consumercompanycustomer_id')
          )
    LOOP
        EXECUTE format('DROP INDEX IF EXISTS public.%I', rec.index_name);
    END LOOP;
END $$;

CREATE INDEX IF NOT EXISTS idx_transaction_inputmeasureunittype_id ON public.transaction USING btree (inputmeasureunittype_id);
CREATE INDEX IF NOT EXISTS idx_transaction_sourcestockorder_id ON public.transaction USING btree (sourcestockorder_id);
CREATE INDEX IF NOT EXISTS idx_stockorder_consumercompanycustomer_id ON public.stockorder USING btree (consumercompanycustomer_id);
